cards.solution:
class Dompet {
  private mutasi: number[] = [];
  static buatDenganSaldo(n: number): Dompet {
    const d = new Dompet();
    d.setor(n);
    return d;
  }
  setor(n: number): void {
    this.mutasi.push(n);
  }
  get saldo(): number {
    return this.mutasi.reduce((a, n) => a + n, 0);
  }
  get jumlahMutasi(): number {
    return this.mutasi.length;
  }
}
const d = Dompet.buatDenganSaldo(20000);
d.setor(5000);
console.log(d.saldo, d.jumlahMutasi);
